    for (int i = n - 2; i >= 0; i--)
    {
        if (a[i] > a[i + 1])
        {
            back = i + 1;
            break;
        }
    }

    // if no reversed subarray is present 
    if (front == -1 && back == -1) 
    {
        for (int i = 0; i < n; i++) 
